      ],
      'casual-chic': [
        'ดูดีแบบไม่ต้องพยายามด้วยการจับคู่ที่ลงตัว',
        'สบายแต่ยังคงดูมีคลาสและเก๋ไก๋',
        'ลุคแคชชวลที่มีความเป็นตัวของตัวเอง',
      ],
      'y2k-revival': [
        'ย้อนยุคสู่ความหวานและสนุกสนานของยุค 2000',
